document.addEventListener('DOMContentLoaded',()=>{const m=document.querySelector('.mapbox');if(!m)return;m.innerHTML='<strong>MAPA DE ANGRA</strong><div class="angra-map"><svg viewBox="0 0 520 300" role="img" aria-label="Mapa ilustrado de Angra dos Reis"><rect width="520" height="300" fill="#b9e2e3"/><path d="M0 0h180c-18 45-10 62 32 77 27 10 23 34 4 52-20 17-11 39 31 48 47 10 63 31 47 123H0z" fill="#f1e8d5"/><path d="M520 0H355c10 30 5 52-19 69-20 14-16 31 14 43 30 12 37 32 10 52-21 16-13 39 26 57 23 11 31 32 28 79h106z" fill="#f1e8d5"/><path d="M125 200c45-42 85-43 130-22s75 16 117-19" fill="none" stroke="#8fc7c5" stroke-width="4" stroke-linecap="round"/><g class="island"><ellipse cx="260" cy="125" rx="70" ry="32"/><ellipse cx="377" cy="195" rx="45" ry="20"/><ellipse cx="175" cy="238" rx="32" ry="15"/></g><g class="map-pin"><circle cx="257" cy="116" r="10"/><circle cx="377" cy="190" r="10"/><circle cx="175" cy="233" r="10"/></g><g class="map-names"><text x="228" y="87">ILHA GRANDE</text><text x="347" y="224">GIPÓIA</text><text x="142" y="264">CATAGUÁS</text><text x="22" y="27">ANGRA DOS REIS</text></g></svg></div><small>Destino atual: <b>Praia do Aventureiro</b></small>';const s=document.createElement('style');s.textContent='.angra-map{height:210px;margin:12px 0;border-radius:17px;overflow:hidden;box-shadow:inset 0 0 0 1px #a4d0d0}.angra-map svg{width:100%;height:100%;display:block}.island ellipse{fill:#6fa89b;stroke:#4d887c;stroke-width:3}.map-pin circle{fill:#f26b4f;stroke:#fff;stroke-width:4}.map-names text{font:700 10px system-ui;letter-spacing:1px;fill:#315d68}.map-names text:first-child{fill:#fff}.mapbox small{display:block;margin-top:8px}';document.head.appendChild(s)});
